const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountFuji = ee.Geometry.Point([138.7274, 35.3606]);
  const region = mountFuji.buffer(20000); // 20km buffer around Mount Fuji

  // 2. Function to calculate NDSI and get mean for a given December
  function getDecemberMeanNDSI(year) {
    const startDate = year + '-12-01';
    const endDate = year + '-12-31';

    // Use MODIS Terra surface reflectance
    const collection = ee.ImageCollection('MODIS/061/MOD09GA')
      .filterDate(startDate, endDate)
      .filterBounds(region);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return {year: year, meanNDSI: null, valid: false, reason: 'no_images'};
    }

    // Calculate NDSI: (Green - SWIR)/(Green + SWIR)
    // MOD09GA bands: B4 (555nm - Green), B6 (1640nm - SWIR)
    const ndsiCollection = collection.map(function(image) {
      const ndsi = image.normalizedDifference(['sur_refl_b04', 'sur_refl_b06']).rename('NDSI');

      // Cloud masking using state_1km band
      const cloudMask = image.select('state_1km').bitwiseAnd(1).eq(0); // Clear sky
      return ndsi.updateMask(cloudMask);
    });

    // Get mean NDSI for the month
    const meanImage = ndsiCollection.mean();
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    });

    const statsInfo = stats.getInfo();
    const meanNDSI = statsInfo.NDSI;
    const pixelCount = statsInfo.NDSI_count;

    if (pixelCount === 0 || meanNDSI === null) {
      return {year: year, meanNDSI: null, valid: false, reason: 'no_valid_pixels'};
    }

    return {year: year, meanNDSI: meanNDSI, valid: true, pixelCount: pixelCount};
  }

  // 3. Analyze all years
  const years = [];
  for (let y = 2005; y <= 2015; y++) years.push(y);
  years.push(2020);

  const results = {};
  let validYears = 0;

  for (const year of years) {
    const result = getDecemberMeanNDSI(year);
    results[year] = result;

    if (result.valid) {
      validYears++;
      console.log(`${year}: NDSI=${result.meanNDSI.toFixed(3)}, Pixels=${result.pixelCount}`);
    } else {
      console.log(`${year}: ${result.reason === 'no_images' ? 'No images' : 'No valid pixels'}`);
    }
  }

  // 4. Check data availability
  if (!results[2020].valid) {
    if (results[2020].reason === 'no_images') {
      console.log("<answer>C1</answer>");
      return;
    } else {
      console.log("<answer>C2</answer>");
      return;
    }
  }

  // Get valid comparison years (2005-2015)
  const comparisonValues = [];
  for (let y = 2005; y <= 2015; y++) {
    if (results[y].valid) {
      comparisonValues.push(results[y].meanNDSI);
    }
  }

  if (comparisonValues.length === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Compare 2020 with historical minimum
  const ndsi2020 = results[2020].meanNDSI;
  const minHistorical = Math.min(...comparisonValues);

  console.log(`2020 NDSI: ${ndsi2020.toFixed(3)}`);
  console.log(`Min 2005-2015: ${minHistorical.toFixed(3)}`);
  console.log(`Valid years: ${comparisonValues.length}/11`);

  // Validation check
  if (ndsi2020 < -1 || ndsi2020 > 1 || minHistorical < -1 || minHistorical > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (ndsi2020 < minHistorical) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
